// VIOC_units_dlc.sqf - agregado por tools/vio_build.py, parche "units_extra_dlc" (copia configurada, no es del
// autor de la mision). Lo llama Init_Common.sqf una vez por bando (west y east), cuando ya estan todas las fabricas,
// escuadras y (si esta) el parche units_extra_qav, en cada maquina (servidor y clientes), como el resto de Init_Common.
// Suma al menu de compra vehiculos de Arma 3 y de sus DLC oficiales (Apex, Tanks, Jets, Helicopters, Contact):
//  - Oeste (sea EE.UU., Ucrania, CDF o Bundeswehr): OTAN; Este (Rusia, ChDKZ o NVA): CSAT;
//  - solo clases que existen, son publicas (scope 2), del bando correcto en la configuracion (1 Oeste, 0 Este),
//    del tipo de la fabrica y que nadie definio ni vende ya (ninguna variante de camuflaje del mismo vehiculo);
//  - version oliva/hex verde (B_T_/O_T_) en mapas boscosos o si "Main Camo" pide invierno/selva; arena en el resto;
//  - no crea niveles de mejora: toma el nivel ORIGINAL (antes de vehicles_start) de un vehiculo equivalente que ya
//    vende esa fabrica (M1A1/T-72 para el Slammer/Varsuk, AH-64/Ka-52 para Blackfoot/Kajman, A-10/Su-25...). Si no
//    hay equivalente, usa el rango 0, 1, 2.. (1.o, 2.o, 3.o.. nivel que ya usa la fabrica) o -1, -2.. (desde arriba);
//  - precio y tiempo con las formulas del autor (CTI_CO_FNC_GetCalculatedUnitsPrize / ...Buildtime) y ese nivel;
//  - se registra con Set_Units.sqf como cualquier unidad de la mision, asi que el parche vehicles_start le aplica la
//    misma regla que a las demas: fabrica ligera y helicopteros de nivel 0-2 disponibles desde el nivel 0. Excepcion:
//    los helicopteros de ataque (Blackfoot, Kajman y los de pilones de los Creator DLC) conservan su nivel, como
//    vehicles_start pide para los de ataque pesados (en naciones con pocos niveles aereos quedarian en 0);
//  - la tripulacion la pone la mision al comprar (CTI_<bando>_Soldier/Crew/Pilot), no el vehiculo;
//  - Scorcher, Sochor, Sandstorm (y el Zamak MRL de la opcion 2) se registran en el menu de artilleria de la mision.
// Creator DLC modernos (Western Sahara, Reaction Forces, Expeditionary Forces): si estan cargados, una pasada por
// CfgVehicles (una sola vez, se guarda en VIOC_DLC_CDLC_POOL) toma sus vehiculos publicos del bando (sin estaticos,
// drones, paracaidas, clases base, artilleria ni vehiculos de servicio), uno por modelo, y les da un nivel conservador: sin armas
// = el primero; ruedas armado = el del medio (blindado 8x8 = penultimo); orugas armado = del medio (blindaje >= 600 =
// el ultimo); helicoptero armado = del medio (con pilones = el ultimo); avion = del medio (armado = el ultimo);
// barco armado = del medio. Maximo 40 por bando.
// Solo el menu de compra: la IA comandante y sus escuadras siguen con los vehiculos de su nacion.
// Parametro de lobby VIOC_DLC_VEHICLES: 0 = no; 1 = si (por defecto, tambien en "Un jugador", donde la mision no lee
// el lobby); 2 = si, y ademas vehiculos de la AAF/LDF (equipo occidental: Kuma, Mora, Gorgon, Strider, Nyx, Hellcat,
// Mohawk, Gryphon, Buzzard, Zamak MRL) en el Oeste.
private ["_side", "_faction", "_classname", "_get", "_turret_main", "_turret_sub", "_roleFound"];
_side = _this;
_faction = "";
private _vd_mode = missionNamespace getVariable ["VIOC_DLC_VEHICLES", 1];
if !(_vd_mode isEqualType 0) then {_vd_mode = 1};
if (_vd_mode <= 0 || {!(_side in [west, east])}) exitWith {};
private _vd_sideCfg = if (_side == west) then {1} else {0};
private _vd_setUnits = compile preprocessFileLineNumbers "Common\Config\Units\Set_Units.sqf";

//--- nivel ORIGINAL de una unidad ya registrada (VIOC_ULVL_<clase> lo guarda Set_Units.sqf antes de vehicles_start); -1 si no
private _vd_fnc_orig = {
	private _vd_v = missionNamespace getVariable (_this select 0);
	if (isNil "_vd_v") exitWith {-1};
	if !(_vd_v isEqualType []) exitWith {-1};
	if (count _vd_v <= CTI_UNIT_UPGRADE) exitWith {-1};
	private _vd_l = missionNamespace getVariable [format ["VIOC_ULVL_%1", _this select 0], _vd_v select CTI_UNIT_UPGRADE];
	if !(_vd_l isEqualType 0) then {_vd_l = _vd_v select CTI_UNIT_UPGRADE};
	if (_vd_l isEqualType 0) then {_vd_l} else {-1}
};

private _vd_fac = [
	["LIGHT", CTI_LIGHT, CTI_FACTORY_LIGHT, CTI_ECONOMY_PRIZE_WHEELED, ["Car"]],
	["HEAVY", CTI_HEAVY, CTI_FACTORY_HEAVY, CTI_ECONOMY_PRIZE_TRACKED, ["Tank"]],
	["AIR", CTI_AIR, CTI_FACTORY_AIR, CTI_ECONOMY_PRIZE_AIR, ["Helicopter", "Plane"]],
	["NAVAL", CTI_NAVAL, CTI_FACTORY_NAVAL, CTI_ECONOMY_PRIZE_NAVAL, ["Ship"]]
];
private _vd_lists = [];
private _vd_levels = [];
{
	private _vd_u = missionNamespace getVariable [format ["CTI_%1_%2Units", _side, _x select 1], []];
	private _vd_lv = [];
	{
		private _vd_l = [_x] call _vd_fnc_orig;
		if (_vd_l >= 0) then {_vd_lv pushBackUnique _vd_l};
	} forEach _vd_u;
	_vd_lv sort true;
	_vd_lists pushBack _vd_u;
	_vd_levels pushBack _vd_lv;
} forEach _vd_fac;

//--- todo lo que ese bando ya vende (para no repetir un vehiculo en otro camuflaje)
private _vd_known = [];
{
	_vd_known append (missionNamespace getVariable [format ["CTI_%1_%2Units", _side, _x], []]);
} forEach (missionNamespace getVariable ["CTI_FACTORIES", [CTI_BARRACKS, CTI_LIGHT, CTI_HEAVY, CTI_AIR, CTI_NAVAL]]);

private _vd_green = (toLower worldName) in ["chernarus", "chernarus_summer", "chernarus_winter", "cup_chernarus_a3", "enoch", "tanoa", "sara", "saralite", "sara_dbe1", "woodland_acr", "bootcamp_acr", "provinggrounds_pmc", "porto", "intro", "eden", "cain", "abel", "noe", "gm_weferlingen_summer", "gm_weferlingen_winter", "cam_lao_nam", "vn_khe_sanh", "vn_the_bra"];
if (!isNil "CTI_CAMO_ACTIVATION") then {
	if (isNil "CTI_US_SIDE") then {
		if (CTI_CAMO_ACTIVATION == 1) then {_vd_green = true}; //--- clasica: "Jungle (APEX)"
	} else {
		if (CTI_CAMO_ACTIVATION == 2) then {_vd_green = false}; //--- CW: "Desert"
		if (CTI_CAMO_ACTIVATION in [1, 3]) then {_vd_green = true}; //--- CW: "Winter" y "Jungle"
	};
};

//--- en "Un jugador" CTI_ECONOMY_PRIZE_ARMED no existe (solo es parametro de lobby): sin el recargo, para no dar precio nil
private _vd_armedOK = !isNil "CTI_ECONOMY_PRIZE_ARMED";
private _vd_added = [];
private _vd_addedCls = [];
private _vd_fnc_add = {
	//--- [clase, indice de fabrica, nivel original, armado, multiplicador, mantener nivel] -> true si quedo en la lista de la fabrica
	params ["_vd_c", "_vd_fi", "_vd_lvl", "_vd_arm", "_vd_mult", ["_vd_keep", false]];
	private _vd_f = _vd_fac select _vd_fi;
	private _vd_price = [_vd_f select 3, _vd_lvl, _vd_arm && _vd_armedOK, _vd_mult] call CTI_CO_FNC_GetCalculatedUnitsPrize;
	private _vd_time = [_vd_f select 2, _vd_lvl] call CTI_CO_FNC_GetCalculatedBuildtime;
	[_side, _faction, [_vd_c], [""], [""], [_vd_price], [_vd_time], [_vd_lvl], [_vd_f select 2], [""], [10]] call _vd_setUnits;
	private _vd_reg = missionNamespace getVariable _vd_c;
	private _vd_units = _vd_lists select _vd_fi;
	if (isNil "_vd_reg" || {_vd_c in _vd_units}) exitWith {false};
	//--- helicoptero de ataque: vehicles_start pasa a 0 los helicopteros de nivel <= 2; este conserva su nivel (como pide ese parche para los de ataque pesados)
	if (_vd_keep && {(_vd_reg select CTI_UNIT_UPGRADE) isEqualType 0} && {(_vd_reg select CTI_UNIT_UPGRADE) < _vd_lvl}) then {_vd_reg set [CTI_UNIT_UPGRADE, _vd_lvl]};
	_vd_units pushBack _vd_c;
	missionNamespace setVariable [format ["CTI_%1_%2Units", _side, _vd_f select 1], _vd_units];
	_vd_known pushBack _vd_c;
	_vd_addedCls pushBack _vd_c;
	_vd_added pushBack [_vd_c, _vd_lvl, _vd_reg select CTI_UNIT_UPGRADE, _vd_price];
	true
};

