if (isNil "_vd_pool") then {
	_vd_pool = [];
	private _vd_cand = "getNumber (_x >> 'scope') == 2 && {getNumber (_x >> 'side') in [0, 1]} && {((toLower configSourceMod _x) in ['ws', 'rf', 'ef']) || {(toLower getText (_x >> 'dlc')) in ['ws', 'rf', 'ef']}}" configClasses (configFile >> "CfgVehicles");
	{
		private _vd_cfg = _x;
		private _vd_c = configName _vd_cfg;
		private _vd_fi = switch (true) do {
			case (_vd_c isKindOf "StaticWeapon" || {_vd_c isKindOf "ParachuteBase"}): {-1};
			case (_vd_c isKindOf "Car"): {0};
			case (_vd_c isKindOf "Tank"): {1};
			case (_vd_c isKindOf "Helicopter" || {_vd_c isKindOf "Plane"}): {2};
			case (_vd_c isKindOf "Ship"): {3};
			default {-1};
		};
		private _vd_m = [getText (_vd_cfg >> "model")] call _vd_fnc_norm;
		if (_vd_fi >= 0 && {_vd_m != ""} && {getNumber (_vd_cfg >> "isUav") < 1} && {getNumber (_vd_cfg >> "hasDriver") > 0} && {(toLower getText (_vd_cfg >> "simulation")) != "submarinex"} && {((toLower _vd_c) find "_base") < 0} && {getNumber (_vd_cfg >> "transportRepair") <= 0} && {getNumber (_vd_cfg >> "transportAmmo") <= 0} && {getNumber (_vd_cfg >> "transportFuel") <= 0} && {getNumber (_vd_cfg >> "attendant") <= 0} && {getNumber (_vd_cfg >> "artilleryScanner") <= 0}) then {
			private _vd_a = [_vd_cfg] call _vd_fnc_armed;
			private _vd_arm = _vd_a select 0;
			//--- rango: 0 = primer nivel, 1 = el del medio, 2 = penultimo, 3 = ultimo
			private _vd_rk = switch (_vd_fi) do {
				case 0: {if (!_vd_arm) then {0} else {if (_vd_c isKindOf "Wheeled_APC_F") then {2} else {1}}};
				case 1: {if (!_vd_arm) then {0} else {if (getNumber (_vd_cfg >> "armor") >= 600) then {3} else {1}}};
				case 2: {if (_vd_c isKindOf "Plane") then {if (_vd_arm) then {3} else {1}} else {if (!_vd_arm) then {0} else {if (_vd_a select 1) then {3} else {1}}}};
				default {if (_vd_arm) then {1} else {0}};
			};
			_vd_pool pushBack [_vd_c, getNumber (_vd_cfg >> "side"), _vd_fi, _vd_arm, _vd_rk, _vd_m];
		};
	} forEach _vd_cand;
	missionNamespace setVariable ["VIOC_DLC_CDLC_POOL", _vd_pool];
};
if (count _vd_pool > 0) then {
	private _vd_models = [];
	{
		private _vd_m = [getText (configFile >> "CfgVehicles" >> _x >> "model")] call _vd_fnc_norm;
		if (_vd_m != "") then {_vd_models pushBackUnique _vd_m};
	} forEach _vd_known;
	private _vd_cnt = 0;
	{
		_x params ["_vd_c", "_vd_sd", "_vd_fi", "_vd_arm", "_vd_rk", "_vd_m"];
		if (_vd_sd == _vd_sideCfg && {_vd_cnt < 40} && {!(_vd_m in _vd_models)} && {!(_vd_c in _vd_known)} && {isNil {missionNamespace getVariable _vd_c}}) then {
			private _vd_lv = _vd_levels select _vd_fi;
			private _vd_n = count _vd_lv;
			if (_vd_n > 0) then {
				private _vd_lvl = switch (_vd_rk) do {
					case 0: {_vd_lv select 0};
					case 1: {_vd_lv select (floor ((_vd_n - 1) / 2))};
					case 2: {_vd_lv select ((_vd_n - 2) max 0)};
					default {_vd_lv select (_vd_n - 1)};
				};
				if ([_vd_c, _vd_fi, _vd_lvl, _vd_arm, 1, _vd_rk == 3] call _vd_fnc_add) then {
					_vd_cnt = _vd_cnt + 1;
					_vd_models pushBack _vd_m;
				};
			};
		};
	} forEach _vd_pool;
};

//--- 3) artilleria: la mision CW no registra estos obuses y lanzacohetes de Arma 3 en su menu de artilleria (y, salvo con
//    "ARTILLERY: Setup" en "Ballistic Computer", apaga la computadora balistica del juego). Se registran con los mismos
//    valores (municion, rafagas y alcances) que el autor usa en su mision clasica, solo si este script los agrego.
private _vd_artyList = missionNamespace getVariable ["CTI_ARTILLERY", []];
{
	_x params ["_vd_acls", "_vd_amags", "_vd_aburst", "_vd_arange"];
	{
		private _vd_a = _x;
		if ((_vd_a in _vd_addedCls) && {!(_vd_a in _vd_artyList)}) then {
			private _vd_ml = [];
			{_vd_ml pushBack (getText (configFile >> "CfgMagazines" >> _x >> "displayName"))} forEach _vd_amags;
			missionNamespace setVariable [format ["CTI_ARTILLERY_%1", _vd_a], [getText (configFile >> "CfgVehicles" >> _vd_a >> "displayName"), _vd_ml, _vd_amags, _vd_aburst, _vd_arange]];
			_vd_artyList pushBack _vd_a;
		};
	} forEach _vd_acls;
} forEach [
	[["B_MBT_01_arty_F", "B_T_MBT_01_arty_F"], ["32Rnd_155mm_Mo_shells", "4Rnd_155mm_Mo_guided", "6Rnd_155mm_Mo_mine", "2Rnd_155mm_Mo_Cluster", "6Rnd_155mm_Mo_smoke", "2Rnd_155mm_Mo_LG", "6Rnd_155mm_Mo_AT_mine"], [1, 2, 4, 8, 16, 32], [[800,4000], [800,7000], [800,10000], [800,20000]]],
	[["O_MBT_02_arty_F", "O_T_MBT_02_arty_ghex_F"], ["32Rnd_155mm_Mo_shells_O", "2Rnd_155mm_Mo_guided_O", "6Rnd_155mm_Mo_mine_O", "2Rnd_155mm_Mo_Cluster_O", "6Rnd_155mm_Mo_smoke_O", "4Rnd_155mm_Mo_LG_O", "6Rnd_155mm_Mo_AT_mine_O"], [1, 2, 4, 8, 16, 32], [[800,4500], [800,7500], [800,10500], [800,20500]]],
	[["B_MBT_01_mlrs_F", "B_T_MBT_01_mlrs_F", "I_Truck_02_MRL_F", "I_E_Truck_02_MRL_F"], ["12Rnd_230mm_rockets"], [1, 2, 3, 6, 12], [[800,4500], [800,7500], [800,10500], [800,20500]]]
];
missionNamespace setVariable ["CTI_ARTILLERY", _vd_artyList];

if (CTI_Log_Level >= CTI_Log_Information) then {["INFORMATION", "FILE: Common\Config\Units\VIOC_units_dlc.sqf", format ["[%1] modo %2, verde %3, [clase, nivel original, nivel, precio]: %4", _side, _vd_mode, _vd_green, _vd_added]] call CTI_CO_FNC_Log};

